// Command isogen generates the Go tests of the isolation matrix: every <module>.yaml of backend/test/isolation
// becomes <module>_test.go (build tag isolation) that runs its rows with matrix.Run.
//
//	go -C backend generate ./test/isolation          # write (also removes generated files without a YAML)
//	go -C backend run ./test/isolation/cmd/isogen -check -dir test/isolation   # exit 1 on drift
//
// Exit codes: 0 ok · 1 format error or drift · 2 usage.
package main

import (
	"bytes"
	"errors"
	"flag"
	"fmt"
	"go/format"
	"io"
	"io/fs"
	"os"
	"slices"
	"strconv"
	"strings"
	"unicode"

	"github.com/ortus/ortus-crm/backend/test/isolation/fixtures"
	"github.com/ortus/ortus-crm/backend/test/isolation/matrix"
)

const (
	exitOK    = 0
	exitFail  = 1
	exitUsage = 2
)

func main() { os.Exit(run(os.Args[1:], os.Stdout, os.Stderr)) }

func run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("isogen", flag.ContinueOnError)
	fs.SetOutput(stderr)
	dir := fs.String("dir", ".", "directory with <module>.yaml (backend/test/isolation)")
	check := fs.Bool("check", false, "do not write; exit 1 when generated files are out of date")
	if err := fs.Parse(args); err != nil {
		return exitUsage
	}
	// All file access goes through os.Root: names come from a directory listing and never leave dir.
	root, err := os.OpenRoot(*dir)
	if err != nil {
		fmt.Fprintf(stderr, "isogen: %v\n", err)
		return exitFail
	}
	defer root.Close()
	want, orphans, err := plan(root)
	if err != nil {
		fmt.Fprintf(stderr, "isogen: %v\n", err)
		return exitFail
	}
	if *check {
		return report(root, want, orphans, stdout, stderr)
	}
	for name, src := range want {
		if err := root.WriteFile(name, src, 0o600); err != nil {
			fmt.Fprintf(stderr, "isogen: %v\n", err)
			return exitFail
		}
	}
	for _, name := range orphans {
		if err := root.Remove(name); err != nil {
			fmt.Fprintf(stderr, "isogen: %v\n", err)
			return exitFail
		}
	}
	fmt.Fprintf(stdout, "isogen: %d matrix files, %d orphans removed\n", len(want), len(orphans))
	return exitOK
}

// report prints the generated files that differ from what the YAML files produce.
func report(root *os.Root, want map[string][]byte, orphans []string, stdout, stderr io.Writer) int {
	var stale []string
	for name, src := range want {
		got, err := root.ReadFile(name)
		if err != nil || !bytes.Equal(got, src) {
			stale = append(stale, name)
		}
	}
	slices.Sort(stale)
	for _, name := range stale {
		fmt.Fprintf(stderr, "isogen: %s is out of date (run go generate ./test/isolation)\n", name)
	}
	for _, name := range orphans {
		fmt.Fprintf(stderr, "isogen: %s is an orphan generated file: its YAML is gone\n", name)
	}
	if len(stale)+len(orphans) > 0 {
		return exitFail
	}
	fmt.Fprintf(stdout, "isogen: %d matrix files up to date\n", len(want))
	return exitOK
}

// plan returns the generated files of dir (name → content) and the generated files without a YAML.
func plan(root *os.Root) (map[string][]byte, []string, error) {
	yamls, err := fs.Glob(root.FS(), "*.yaml")
	if err != nil {
		return nil, nil, err
	}
	cat := fixtures.Default()
	want := map[string][]byte{}
	var errs []error
	for _, name := range yamls {
		data, err := root.ReadFile(name)
		if err != nil {
			return nil, nil, err
		}
		src, err := Generate(name, data, cat)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		want[strings.TrimSuffix(name, ".yaml")+"_test.go"] = src
	}
	if len(errs) > 0 {
		return nil, nil, errors.Join(errs...)
	}
	tests, err := fs.Glob(root.FS(), "*_test.go")
	if err != nil {
		return nil, nil, err
	}
	var orphans []string
	for _, name := range tests {
		if _, ok := want[name]; ok {
			continue
		}
		data, err := root.ReadFile(name)
		if err != nil {
			return nil, nil, err
		}
		if bytes.HasPrefix(data, []byte(headerPrefix)) {
			orphans = append(orphans, name)
		}
	}
	return want, orphans, nil
}

const headerPrefix = "// Code generated by isogen from "

func header(yamlName string) string { return headerPrefix + yamlName + ". DO NOT EDIT.\n" }

// goNames returns the variable and the test function of a module: fleet_units → fleetUnitsMatrix, TestIsolationFleetUnits.
func goNames(module string) (varName, testName string) {
	var b strings.Builder
	for part := range strings.SplitSeq(module, "_") {
		r := []rune(part)
		r[0] = unicode.ToUpper(r[0])
		b.WriteString(string(r))
	}
	camel := b.String()
	r := []rune(camel)
	r[0] = unicode.ToLower(r[0])
	return string(r) + "Matrix", "TestIsolation" + camel
}

// Generate checks one matrix file and returns its Go test file (gofmt-formatted).
func Generate(name string, data []byte, cat fixtures.Catalog) ([]byte, error) {
	f, err := matrix.Parse(name, data, cat)
	if err != nil {
		return nil, err
	}
	varName, testName := goNames(f.Module)
	var b strings.Builder
	b.WriteString(header(name))
	b.WriteString("\n//go:build isolation\n\npackage isolation\n\n")
	b.WriteString("import (\n\t\"testing\"\n\n\t\"github.com/ortus/ortus-crm/backend/test/isolation/matrix\"\n)\n\n")
	fmt.Fprintf(&b, "// %s holds the rows of %s (format: README.md).\n", varName, name)
	fmt.Fprintf(&b, "var %s = matrix.File{\nModule: %s,\nEndpoints: []matrix.Endpoint{\n", varName, strconv.Quote(f.Module))
	for _, ep := range f.Endpoints {
		writeEndpoint(&b, ep)
	}
	b.WriteString("},\n}\n\n")
	fmt.Fprintf(&b, "func %s(t *testing.T) {\n\tt.Parallel()\n\tmatrix.Run(t, suite, %s)\n}\n", testName, varName)
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("isogen: %s: gofmt: %w", name, err)
	}
	return src, nil
}

func writeEndpoint(b *strings.Builder, ep matrix.Endpoint) {
	b.WriteString("{\n")
	field(b, "Op", ep.Op)
	field(b, "Method", ep.Method)
	field(b, "Path", ep.Path)
	field(b, "Channel", ep.Channel)
	field(b, "Pending", ep.Pending)
	b.WriteString("Rows: []matrix.Row{\n")
	for _, r := range ep.Rows {
		b.WriteString("{\n")
		field(b, "Actor", r.Actor)
		if len(r.Params) > 0 {
			keys := make([]string, 0, len(r.Params))
			for k := range r.Params {
				keys = append(keys, k)
			}
			slices.Sort(keys)
			pairs := make([]string, 0, len(keys))
			for _, k := range keys {
				pairs = append(pairs, strconv.Quote(k)+": "+strconv.Quote(r.Params[k]))
			}
			fmt.Fprintf(b, "Params: map[string]string{%s},\n", strings.Join(pairs, ", "))
		}
		fmt.Fprintf(b, "Status: %d,\n", r.Status)
		field(b, "Code", r.Code)
		list(b, "Present", r.Present)
		list(b, "Absent", r.Absent)
		field(b, "Body", r.Body)
		field(b, "Note", r.Note)
		b.WriteString("},\n")
	}
	b.WriteString("},\n},\n")
}

func field(b *strings.Builder, name, value string) {
	if value != "" {
		fmt.Fprintf(b, "%s: %s,\n", name, strconv.Quote(value))
	}
}

func list(b *strings.Builder, name string, values []string) {
	if len(values) == 0 {
		return
	}
	quoted := make([]string, len(values))
	for i, v := range values {
		quoted[i] = strconv.Quote(v)
	}
	fmt.Fprintf(b, "%s: []string{%s},\n", name, strings.Join(quoted, ", "))
}
